import { NotFoundError, notificationResource, requireFound } from "./_support";
import type {
  ListNotificationsInput,
  MarkNotificationReadInput,
  UpdateNotificationPreferenceInput,
} from "@/schemas/notification";
import type { LimitedResource } from "@/types/billing";
import type { IssueId, OrgId, Page, UserId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { PermissionAction } from "@/types/permission";
import type {
  Notification,
  NotificationChannel,
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export type NotificationPayload = {
  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const rows = [];

  for (const recipientId of new Set(recipients)) {
    if (recipientId === payload.actorId) continue;

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    const channels = resolveChannels(preference, flags);
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      channels,
    });
  }

  return notificationRepo.insertNotifications(orgId, rows);
}

export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  assertOwnInbox(actor, input.recipientId, "notification:read");
  assertCan(
    actor,
    "notification:read",
    notificationResource(input.orgId, input.recipientId),
  );
  // The inbox is the in-app channel only. A row kept for email or the digest
  // stays out of every page, so paging neither drops nor repeats an entry.
  return notificationRepo.listNotifications({ ...input, channel: "in_app" });
}

export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, actor.userId),
  );
  const existing = await notificationRepo.findNotificationById(
    input.orgId,
    input.notificationId,
  );
  if (!existing) {
    throw new NotFoundError("Notification", input.notificationId);
  }
  assertOwnInbox(actor, existing.recipientId, "notification:manage");
  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

export async function markAllRead(
  actor: Actor,
  orgId: OrgId,
): Promise<number> {
  assertOrgScope(actor, orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(orgId, actor.userId),
  );
  return notificationRepo.markAllRead(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
}

export async function updatePreference(
  actor: Actor,
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  assertOrgScope(actor, input.orgId);
  assertOwnInbox(actor, input.userId, "notification:manage");
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, input.userId),
  );
  return preferenceRepo.upsertPreference(input);
}

/**
 * Tells the workspace owner that a write was refused because the plan has no
 * room. While an unread alert for the same resource is still open, further
 * refusals add nothing; a different resource is its own alert. Callers that
 * only recount usage must not call this — a recount refuses nothing.
 */
export async function recordPlanLimitRefusal(
  orgId: OrgId,
  resource: LimitedResource,
): Promise<void> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return;

  const owners = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: 100,
    cursor: null,
  });
  const recipientIds = new Set<UserId>(owners.items.map((member) => member.userId));
  recipientIds.add(org.ownerId);

  const marker = planLimitMarker(resource);
  const href = settingsPath(org.slug, "billing");

  for (const recipientId of recipientIds) {
    const open = await notificationRepo.listNotifications({
      orgId,
      recipientId,
      unreadOnly: true,
      kind: ["plan_limit_reached"],
      limit: 50,
      cursor: null,
    });
    if (open.items.some((notification) => notification.body.includes(marker))) {
      continue;
    }

    await notify(orgId, "plan_limit_reached", [recipientId], {
      title: "Plan limit reached",
      body: `This workspace has no room for another ${resource} (${marker}).`,
      href,
      actorId: null,
    });
  }
}

/** Inboxes are personal: role never grants access to someone else's rows. */
function assertOwnInbox(
  actor: Actor,
  subjectUserId: UserId,
  action: Extract<PermissionAction, "notification:read" | "notification:manage">,
): void {
  if (subjectUserId === actor.userId) return;
  throw new PermissionDeniedError(action, {
    allowed: false,
    action,
    resourceKind: "notification",
    reason: "denied_by_role",
  });
}

function planLimitMarker(resource: LimitedResource): string {
  return `resource:${resource}`;
}

/** Issue page the app actually serves: `/{org}/projects/{project}/issues/{n}`. */
async function hrefForIssue(orgId: OrgId, issueId: IssueId): Promise<string> {
  const org = await orgRepo.findOrgById(orgId);
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!org) return "/";
  if (!issue) return orgPath(org.slug);
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project) return orgPath(org.slug);
  return issuePath(org.slug, project.slug, issue.number);
}

/**
 * Turns a stored preference into the channels one notification will use.
 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
 * the email channel additionally requires the org's `digest_email` plan flag.
 */
export function resolveChannels(
  preference: NotificationPreference | null,
  flags: FlagContext,
): readonly NotificationChannel[] {
  if (preference === null) return DEFAULT_CHANNELS;

  const channels: NotificationChannel[] = [];
  if (preference.inApp) channels.push("in_app");

  const emailAllowed =
    preference.email &&
    (!preference.digestOnly || isEnabled("digest_email", flags));

  if (emailAllowed) channels.push("email");
  return channels;
}

/**
 * The bus wiring. Attached at module load rather than from `event-registry`
 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    await notifyAssigned(
      payload.orgId,
      payload.issueId,
      payload.assigneeId,
      payload.actorId,
    );
  });

  subscribe("issue.assigned", async (payload) => {
    await notifyAssigned(
      payload.orgId,
      payload.issueId,
      payload.assigneeId,
      payload.actorId,
    );
  });

  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue?.assigneeId) return;
    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "An issue changed status",
      body: `Issue ${issue.number} moved from ${payload.from} to ${payload.to}`,
      href: await hrefForIssue(payload.orgId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: await hrefForIssue(payload.orgId, payload.issueId),
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];
    const href = await hrefForIssue(payload.orgId, payload.issueId);

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The owner hears that someone joined. The person who joined does not get
  // an alert about themselves.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const owners = await memberRepo.listMembers({
      orgId: payload.orgId,
      role: "owner",
      limit: 100,
      cursor: null,
    });
    const recipients = new Set<UserId>(
      owners.items.map((member) => member.userId),
    );
    recipients.add(org.ownerId);
    recipients.delete(payload.userId);
    if (recipients.size === 0) return;

    await notify(payload.orgId, "member_joined", [...recipients], {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: settingsPath(org.slug, "members"),
      actorId: payload.userId,
    });
  });
}

async function notifyAssigned(
  orgId: OrgId,
  issueId: IssueId,
  assigneeId: UserId,
  actorId: UserId | null,
): Promise<void> {
  await notify(orgId, "issue_assigned", [assigneeId], {
    title: "You were assigned an issue",
    body: `Issue ${issueId} is now yours`,
    href: await hrefForIssue(orgId, issueId),
    actorId,
  });
}

registerFanOut();
