input.new_string:
/** Routes the app actually serves, never a bare `/issues/{id}` path. */
async function hrefFor(
  orgId: OrgId,
  kind: SearchSubjectKind,
  subjectId: string,
): Promise<string> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return "/";

  if (kind === "project") {
    const project = await projectRepo.findProjectById(
      orgId,
      subjectId as ProjectId,
    );
    return project ? projectPath(org.slug, project.slug) : orgPath(org.slug);
  }

  const issueId =
    kind === "issue"
      ? (subjectId as IssueId)
      : (
          await commentRepo.findCommentById(orgId, subjectId as CommentId)
        )?.issueId;

  if (issueId === undefined) return orgPath(org.slug);

  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return orgPath(org.slug);
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project) return orgPath(org.slug);
  return issuePath(org.slug, project.slug, issue.number);
}

